/** 收藏数据的归属键。用角色卡的 avatar 文件名，改名不影响。 */
export type CharacterKey = string;

/** 没有选中任何角色卡时的兜底归属。 */
export const NO_CHARACTER = 'none' as const;

/** 把角色卡的 avatar 文件名转成归属键。 */
export function avatar_key(avatar: string): CharacterKey {
  return `avatar:${avatar}`;
}

/** 一条文本收藏。只存正文，不含状态栏与时间组件。 */
export interface TextItem {
  id: string;
  character_key: CharacterKey;
  title: string;
  content: string;
  created_at: number;
  /** 来源楼层号；手工录入时为 null。 */
  source_message_id: number | null;
}

/**
 * 一张截图的元信息。
 * 图片本身放在另一个 store 里，这样列图库时不用把所有大图都读进内存。
 */
export interface ShotMeta {
  id: string;
  character_key: CharacterKey;
  title: string;
  created_at: number;
  width: number;
  height: number;
  bytes: number;
  starred: boolean;
  /** 列表用的缩略图，小图，可以直接内联存。 */
  thumb: Blob | null;
}

/** 番外指令的一级文件夹。 */
export interface InstructionFolder {
  id: string;
  name: string;
  created_at: number;
}

/** 一条番外指令。folder_id 为 null 表示「未分类」。 */
export interface InstructionItem {
  id: string;
  folder_id: string | null;
  title: string;
  content: string;
  created_at: number;
  updated_at: number;
}

/** 文本收藏侧的一条替换规则。 */
export interface ReplaceRule {
  from: string;
  to: string;
}

/** 按角色保存的过滤设置。只影响截图与预览，不改动原聊天内容。 */
/** 截图的底色款式。 */
export type ShotThemeKind = 'classic' | 'inverted' | 'custom';

export interface CharacterPrefs {
  character_key: CharacterKey;
  /**
   * 清洗标签。收藏楼层时，这些标签连同里面的内容一起丢掉，只留标签外的正文。
   * 用来滤掉状态栏、时间组件这类嵌在楼层里的结构。
   */
  clean_tags: string[];
  /** 截图侧：出图时把某些词换成别的词。 */
  shot_replace_rules: ReplaceRule[];
  shot_replace_enabled: boolean;
  /** 截图底色：经典白底、黑底白字、或自定义。 */
  shot_theme: ShotThemeKind;
  /** 自定义底色时的背景色。 */
  shot_background: string;
  /** 自定义底色时的字体色。 */
  shot_ink: string;
  /** 文本侧：只看不改的显示替换。 */
  replace_rules: ReplaceRule[];
  replace_enabled: boolean;
}

export function empty_prefs(character_key: CharacterKey): CharacterPrefs {
  return {
    character_key,
    clean_tags: [],
    shot_replace_rules: [],
    shot_replace_enabled: false,
    shot_theme: 'classic',
    shot_background: '#ffffff',
    shot_ink: '#17171a',
    replace_rules: [],
    replace_enabled: false,
  };
}
