import { el, shadow_layer } from './dom';

/** 轻提示。整屏只保留一条，后出现的替换先出现的。 */

let current: { node: HTMLElement; timer: number } | null = null;

export function toast(message: string, duration_ms = 2400): void {
  const layer = shadow_layer();
  if (!layer) return;
  if (current) {
    window.clearTimeout(current.timer);
    current.node.remove();
    current = null;
  }
  const node = el('div', { class: 'yj-toast', text: message });
  layer.append(node);
  const timer = window.setTimeout(() => {
    node.remove();
    current = null;
  }, duration_ms);
  current = { node, timer };
}
