/** 把文字类备份导出成 JSON 文件。手机上会走浏览器的下载，电脑上是下载对话框。 */

import { export_text_backup } from '../core/store';

function stamp(): string {
  const date = new Date();
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${date.getFullYear()}${pad(date.getMonth() + 1)}${pad(date.getDate())}-${pad(date.getHours())}${pad(date.getMinutes())}`;
}

/** 把一个 Blob 存到本地。手机上会进浏览器的下载目录，电脑上会弹下载。 */
export function download_blob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.style.display = 'none';
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => {
    URL.revokeObjectURL(url);
  }, 2000);
}

export async function download_backup(): Promise<void> {
  const data = await export_text_backup();
  download_blob(
    new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }),
    `月季管家备份-${stamp()}.json`,
  );
}

/** 给导出的图片起个不会重名的文件名。 */
export function shot_filename(title: string): string {
  const safe =
    title
      .trim()
      .replace(/[\\/:*?"<>|\s]+/g, '-')
      .slice(0, 40) || '截图';
  return `月季管家-${safe}-${stamp()}.jpg`;
}
