/**
 * 截图排版内核。
 *
 * 这里是纯函数：只算每段文字放在哪个位置、总共多高，不碰 canvas。
 * 好处是可以在没有浏览器的环境里直接测排版逻辑，
 * 宽度测量由外部传进来（真实环境用 canvas 的 measureText，测试里用假测量器）。
 */

export interface ShotBlock {
  /** 说话人。空字符串表示旁白，不画名字。 */
  name: string;
  text: string;
  is_user: boolean;
}

export interface ShotStyle {
  /** 逻辑宽度，单位是 CSS 像素。 */
  width: number;
  font_size: number;
  line_height: number;
  padding: number;
  /** 两个楼层之间的间距。 */
  block_gap: number;
}

export interface ShotLayoutItem {
  kind: 'title' | 'divider' | 'name' | 'text' | 'footer';
  text: string;
  x: number;
  y: number;
  size: number;
  bold: boolean;
}

export interface ShotLayout {
  items: ShotLayoutItem[];
  width: number;
  height: number;
  used_blocks: number;
  total_blocks: number;
  truncated: boolean;
}

export interface ShotLayoutInput {
  blocks: ShotBlock[];
  style: ShotStyle;
  title: string;
  footer: string;
  /** 高度上限（逻辑像素）。超了就截断并在结果里标出来。 */
  max_height: number;
}

/** 量一段文字在给定字号下有多宽。 */
export type ShotMeasure = (text: string, size: number, bold: boolean) => number;

/** 按可用宽度把一段文字折行。 */
export function wrap_text(
  text: string,
  size: number,
  bold: boolean,
  max_width: number,
  measure: ShotMeasure,
): string[] {
  const lines: string[] = [];
  for (const paragraph of text.split('\n')) {
    const clean = paragraph.trim();
    if (!clean) {
      lines.push('');
      continue;
    }
    let line = '';
    let width = 0;
    for (const char of clean) {
      const char_width = measure(char, size, bold);
      if (width + char_width > max_width && line) {
        // 英文尽量在空格处断，不要把一个单词劈成两半。
        const space = line.lastIndexOf(' ');
        if (space > 0 && space > line.length * 0.6) {
          lines.push(line.slice(0, space));
          line = `${line.slice(space + 1)}${char}`;
        } else {
          lines.push(line);
          line = char;
        }
        width = measure(line, size, bold);
      } else {
        line += char;
        width += char_width;
      }
    }
    lines.push(line);
  }
  return lines;
}

export function layout_shot(input: ShotLayoutInput, measure: ShotMeasure): ShotLayout {
  const { blocks, style, title, footer, max_height } = input;
  const items: ShotLayoutItem[] = [];
  const content_width = Math.max(40, style.width - style.padding * 2);
  const name_size = Math.round(style.font_size * 0.82);
  const name_height = Math.round(name_size * 2);
  const title_size = Math.round(style.font_size * 1.2);
  const footer_size = Math.round(style.font_size * 0.72);
  let y = style.padding;
  let used_blocks = 0;
  let truncated = false;

  if (title.trim()) {
    const title_lines = wrap_text(title.trim(), title_size, true, content_width, measure);
    for (const line of title_lines) {
      items.push({ kind: 'title', text: line, x: style.padding, y, size: title_size, bold: true });
      y += Math.round(title_size * 1.5);
    }
    y += 4;
    items.push({ kind: 'divider', text: '', x: style.padding, y, size: 0, bold: false });
    y += Math.round(style.font_size * 1.1);
  }

  for (const block of blocks) {
    // 预判这一层加进去会不会超高。超高就停在这里，后面的楼层不要了。
    const rough = block.name ? name_height + Math.round(style.font_size * 1.5) + style.block_gap : style.block_gap;
    if (y + rough > max_height - style.padding) {
      truncated = true;
      break;
    }

    if (block.name) {
      items.push({
        kind: 'name',
        text: block.name,
        x: style.padding,
        y,
        size: name_size,
        bold: true,
      });
      y += name_height;
    }

    const lines = wrap_text(block.text, style.font_size, false, content_width, measure);
    for (const line of lines) {
      if (y + style.line_height > max_height - style.padding) {
        truncated = true;
        break;
      }
      if (line) {
        items.push({ kind: 'text', text: line, x: style.padding, y, size: style.font_size, bold: false });
      }
      y += style.line_height;
    }
    if (truncated) break;

    y += style.block_gap;
    used_blocks += 1;
  }

  const body_bottom = Math.max(y - style.block_gap, style.padding);

  if (footer.trim()) {
    const footer_y = body_bottom + Math.round(style.font_size * 0.9);
    items.push({
      kind: 'footer',
      text: footer.trim(),
      x: style.padding,
      y: footer_y,
      size: footer_size,
      bold: false,
    });
    y = footer_y + Math.round(footer_size * 1.8);
  } else {
    y = body_bottom;
  }

  return {
    items,
    width: style.width,
    height: Math.max(style.padding * 2, y + style.padding),
    used_blocks,
    total_blocks: blocks.length,
    truncated,
  };
}
