import { SHOT_THEMES, resolve_shot_theme } from '../../core/shot_canvas';
import * as store from '../../core/store';
import type { CharacterKey, CharacterPrefs, ReplaceRule, ShotThemeKind } from '../../core/types';
import { confirm_dialog } from '../dialog';
import { el, on } from '../dom';
import { icon } from '../icons';
import { toast } from '../toast';

/** 截图侧设置：出图前的替换、底色款式、批量清理。 */

export interface ShotToolsHandlers {
  on_back: () => void;
  on_changed: (prefs: CharacterPrefs) => void;
  /** 批量删完之后让外层重新拉列表。 */
  on_cleared: () => void;
}

const THEME_LABELS: Array<{ kind: ShotThemeKind; label: string }> = [
  { kind: 'classic', label: '经典白底' },
  { kind: 'inverted', label: '黑底白字' },
  { kind: 'custom', label: '自定义' },
];

export function render_shot_tools(
  character_key: CharacterKey,
  prefs: CharacterPrefs,
  handlers: ShotToolsHandlers,
): HTMLElement {
  let current: CharacterPrefs = { ...prefs, shot_replace_rules: prefs.shot_replace_rules.map(rule => ({ ...rule })) };

  const back = el('button', {
    class: 'yj-iconbtn yj-ws__back',
    html: icon('back', 19),
    title: '返回截图库',
    attrs: { type: 'button', 'aria-label': '返回截图库' },
  });
  on<Event>(back, 'click', () => {
    handlers.on_back();
  });

  const head = el('section', { class: 'yj-ws__head' }, [back, el('div', { class: 'yj-ws__title', text: '截图设置' })]);

  async function persist(next: CharacterPrefs, message: string): Promise<void> {
    current = next;
    render();
    try {
      await store.put_prefs(current);
      handlers.on_changed(current);
      toast(message);
    } catch (error) {
      console.warn('[月季管家] 保存截图设置失败', error);
      toast('保存失败');
    }
  }

  /* ---------------------------------------------------------- 替换名词 */

  const from_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '要替换掉的词', enterkeyhint: 'next' },
  });
  const to_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '换成什么', enterkeyhint: 'done' },
  });
  const rule_add = el('button', {
    class: 'yj-iconbtn yj-search__add yj-tools__add--rule',
    html: icon('plus', 19),
    title: '添加规则',
    attrs: { type: 'button', 'aria-label': '添加规则' },
  });
  const rule_list = el('div', { class: 'yj-card' });
  const rule_switch = el('button', { class: 'yj-btn yj-btn--ghost', attrs: { type: 'button' } });

  function add_rule(): void {
    const from = from_input.value.trim();
    if (!from) {
      toast('先写要替换掉的词');
      return;
    }
    if (current.shot_replace_rules.some(rule => rule.from === from)) {
      toast('这个词已经有规则了');
      return;
    }
    const to = to_input.value.trim();
    from_input.value = '';
    to_input.value = '';
    const rules: ReplaceRule[] = [...current.shot_replace_rules, { from, to }];
    void persist({ ...current, shot_replace_rules: rules, shot_replace_enabled: true }, '已添加，出图时会按它替换');
  }

  on<Event>(rule_add, 'click', add_rule);
  on<KeyboardEvent>(to_input, 'keydown', event => {
    if (event.key === 'Enter') add_rule();
  });
  on<Event>(rule_switch, 'click', () => {
    void persist(
      { ...current, shot_replace_enabled: !current.shot_replace_enabled },
      current.shot_replace_enabled ? '已关闭替换' : '已开启替换',
    );
  });

  function render_rules(): void {
    rule_list.replaceChildren();
    if (!current.shot_replace_rules.length) {
      rule_list.classList.add('yj-card--plain');
      rule_list.append(el('div', { class: 'yj-empty__text', text: '还没有替换规则。' }));
      return;
    }
    rule_list.classList.remove('yj-card--plain');
    for (const rule of current.shot_replace_rules) {
      const trash = el('button', {
        class: 'yj-iconbtn yj-row__action yj-row__trash',
        html: icon('trash', 17),
        title: '删除',
        attrs: { type: 'button', 'aria-label': '删除' },
      });
      on<Event>(trash, 'click', () => {
        void persist(
          {
            ...current,
            shot_replace_rules: current.shot_replace_rules.filter(item => item.from !== rule.from),
          },
          '已删除替换规则',
        );
      });
      rule_list.append(
        el('div', { class: 'yj-row' }, [
          el('div', { class: 'yj-row__main' }, [
            el('div', { class: 'yj-row__title', text: rule.from }),
            el('div', { class: 'yj-row__meta', text: `换成「${rule.to || '（删掉）'}」` }),
          ]),
          trash,
        ]),
      );
    }
  }

  /* ---------------------------------------------------------- 底色 */

  const preview_box = el('div', { class: 'yj-theme-preview' });

  const background_input = el('input', {
    class: 'yj-theme-color',
    attrs: { type: 'color' },
  });
  const ink_input = el('input', {
    class: 'yj-theme-color',
    attrs: { type: 'color' },
  });

  function render_colors(): void {
    background_input.value = current.shot_background;
    ink_input.value = current.shot_ink;
    const theme = resolve_shot_theme(current.shot_theme, current.shot_background, current.shot_ink);
    preview_box.style.background = theme.background;
    preview_box.style.color = theme.ink;
    preview_box.style.borderColor = theme.line;
  }

  on<Event>(background_input, 'input', () => {
    void persist({ ...current, shot_background: background_input.value, shot_theme: 'custom' }, '底色已更新');
  });
  on<Event>(ink_input, 'input', () => {
    void persist({ ...current, shot_ink: ink_input.value, shot_theme: 'custom' }, '字色已更新');
  });

  function render_theme(): void {
    render_colors();
    background_input.parentElement?.style.setProperty('display', current.shot_theme === 'custom' ? '' : 'none');
    ink_input.parentElement?.style.setProperty('display', current.shot_theme === 'custom' ? '' : 'none');
  }

  /* ---------------------------------------------------------- 批量清理 */

  async function clear_shots(only_unstarred: boolean): Promise<void> {
    const shots = await store.list_shots(character_key);
    const count = only_unstarred ? shots.filter(item => !item.starred).length : shots.length;
    if (!count) {
      toast(only_unstarred ? '没有未星标的截图' : '图库是空的');
      return;
    }
    const ok = await confirm_dialog({
      title: only_unstarred ? '删除未星标的截图？' : '清空整个截图库？',
      message: `会删掉 ${count} 张，删掉之后就找不回来了。${only_unstarred ? '加过星标的会留下。' : ''}`,
      confirm_text: '删除',
      danger: true,
    });
    if (!ok) return;
    try {
      const removed = await store.delete_shots(character_key, { only_unstarred });
      toast(`已删除 ${removed} 张`);
      handlers.on_cleared();
    } catch (error) {
      console.warn('[月季管家] 批量删除截图失败', error);
      toast('删除失败');
    }
  }

  const clear_unstarred = el('button', {
    class: 'yj-btn yj-btn--ghost yj-export__button',
    text: '删除未星标的截图',
    attrs: { type: 'button' },
  });
  on<Event>(clear_unstarred, 'click', () => {
    void clear_shots(true);
  });
  const clear_all = el('button', {
    class: 'yj-btn yj-btn--danger yj-export__button',
    text: '清空整个截图库',
    attrs: { type: 'button' },
  });
  on<Event>(clear_all, 'click', () => {
    void clear_shots(false);
  });

  /* ---------------------------------------------------------- 组装 */

  const container = el('section', { class: 'yj-page' });

  function render(): void {
    rule_switch.textContent = current.shot_replace_enabled ? '替换已开启，点此关闭' : '替换已关闭，点此开启';
    render_rules();
    render_theme();

    const theme_segments = THEME_LABELS.map(item => {
      const button = el('button', {
        class: `yj-segment${current.shot_theme === item.kind ? ' is-active' : ''}`,
        text: item.label,
        attrs: { type: 'button' },
      });
      on<Event>(button, 'click', () => {
        void persist({ ...current, shot_theme: item.kind }, '底色已更新');
      });
      return button;
    });

    container.replaceChildren(
      head,
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '替换名词' }),
          el('div', { class: 'yj-section__hint', text: '出图时改' }),
        ]),
        el('div', {
          class: 'yj-note',
          text: '出图前把正文里的某些词换成别的词。例如把真名换成代称，或者把不想露出的词清掉（换成什么留空就是删掉）。原聊天内容一点不动。',
        }),
        el('div', {
          class: 'yj-note',
          text: '清洗标签在文本处理页里设置，出图和收藏文本共用同一份。',
        }),
        el('div', { class: 'yj-search' }, [
          from_input,
          el('div', { class: 'yj-search__icon', html: icon('back', 15) }),
          to_input,
          rule_add,
        ]),
        rule_list,
        el('div', { class: 'yj-section' }, [rule_switch]),
      ]),
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '出图底色' }),
          el('div', { class: 'yj-section__hint', text: '看右边效果' }),
        ]),
        el('div', { class: 'yj-segmented' }, theme_segments),
        el('div', { class: 'yj-theme-row' }, [
          el('label', { class: 'yj-theme-pick' }, [el('span', { text: '背景' }), background_input]),
          el('label', { class: 'yj-theme-pick' }, [el('span', { text: '字体' }), ink_input]),
        ]),
        preview_box,
      ]),
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '清理' }),
          el('div', { class: 'yj-section__hint', text: '删了找不回' }),
        ]),
        el('div', { class: 'yj-card yj-card--plain yj-export' }, [clear_unstarred, clear_all]),
      ]),
    );
  }

  preview_box.append(
    el('div', { class: 'yj-theme-preview__title', text: '她抬头看了你一眼。' }),
    el('div', { class: 'yj-theme-preview__name', text: '沈知夏' }),
    el('div', { class: 'yj-theme-preview__body', text: '窗台上的月季开了第三朵，比前两朵都要小一些。' }),
  );

  render();
  return container;
}

/** 经典款与黑底白字款的取色，给外部参考用。 */
export const SHOT_THEME_SAMPLES = SHOT_THEMES;
