import * as store from '../core/store';
import type { ShotMeta } from '../core/types';
import { confirm_dialog } from './dialog';
import { download_blob, shot_filename } from './download';
import { el, on, shadow_layer } from './dom';
import { relative_time } from './format';
import { icon } from './icons';
import { toast } from './toast';

/** 截图查看器。点图库里任意一张打开，能看大图、保存到本地、加星标、删除。 */

export interface ViewerHandlers {
  /** 数据被改过之后让外层重新拉列表。 */
  on_changed: () => void;
}

export function open_shot_viewer(item: ShotMeta, handlers: ViewerHandlers): void {
  const layer = shadow_layer();
  if (!layer) return;

  let url: string | null = null;
  let starred = item.starred;
  const disposers: Array<() => void> = [];

  const title_node = el('div', { class: 'yj-panel__title', text: item.title || '未命名' });
  const meta_node = el('div', {
    class: 'yj-row__meta',
    text: `${relative_time(item.created_at)}  ${item.width}  ${item.height} 像素`,
  });

  const star_button = el('button', {
    class: 'yj-iconbtn yj-viewer__star',
    html: icon('star', 19),
    attrs: { type: 'button', 'aria-label': '星标' },
  });
  const save_button = el('button', {
    class: 'yj-iconbtn',
    html: icon('download', 19),
    title: '保存到本地',
    attrs: { type: 'button', 'aria-label': '保存到本地' },
  });
  const trash_button = el('button', {
    class: 'yj-iconbtn',
    html: icon('trash', 19),
    title: '删除',
    attrs: { type: 'button', 'aria-label': '删除' },
  });
  const close_button = el('button', {
    class: 'yj-iconbtn yj-panel__close',
    html: icon('close', 19),
    title: '关闭',
    attrs: { type: 'button', 'aria-label': '关闭' },
  });

  const bar = el('div', { class: 'yj-panel__bar' }, [
    el('div', { class: 'yj-panel__head' }, [title_node, meta_node]),
    el('div', { class: 'yj-panel__actions' }, [star_button, save_button, trash_button, close_button]),
  ]);

  const image_box = el('div', { class: 'yj-viewer__stage' });
  const body = el('div', { class: 'yj-viewer__body' }, [image_box]);
  const root = el('div', { class: 'yj-panel yj-viewer' }, [bar, body]);
  const backdrop = el('div', { class: 'yj-backdrop' });
  const wrapper = el('div', { class: 'yj-viewer__layer' }, [backdrop, root]);
  layer.append(wrapper);

  let blob: Blob | null = null;

  async function load_image(): Promise<void> {
    image_box.replaceChildren(el('div', { class: 'yj-empty__text', text: '正在读取图片' }));
    try {
      blob = await store.get_shot_image(item.id);
    } catch (error) {
      console.warn('[月季管家] 读取截图失败', error);
      blob = null;
    }
    if (!wrapper.isConnected) return;
    if (!blob) {
      image_box.replaceChildren(el('div', { class: 'yj-empty__text', text: '这张图读不出来了。' }));
      return;
    }
    if (url) URL.revokeObjectURL(url);
    url = URL.createObjectURL(blob);
    image_box.replaceChildren(el('img', { class: 'yj-viewer__image', attrs: { src: url, alt: item.title || '截图' } }));
  }

  function sync_star(): void {
    star_button.classList.toggle('is-on', starred);
    star_button.title = starred ? '取消星标' : '加星标';
  }

  async function toggle_star(): Promise<void> {
    try {
      starred = !starred;
      await store.set_shot_starred(item.id, starred);
      sync_star();
      handlers.on_changed();
    } catch (error) {
      console.warn('[月季管家] 更新星标失败', error);
      toast('更新星标失败');
    }
  }

  async function remove(): Promise<void> {
    const ok = await confirm_dialog({
      title: '确认删除？',
      message: `「${item.title || '未命名'}」连同图片一起删掉，找不回来。`,
      confirm_text: '删除',
      danger: true,
    });
    if (!ok) return;
    try {
      await store.delete_shot(item.id);
      toast('已删除');
      handlers.on_changed();
      close();
    } catch (error) {
      console.warn('[月季管家] 删除截图失败', error);
      toast('删除失败');
    }
  }

  function close(): void {
    for (const dispose of disposers) dispose();
    if (url) URL.revokeObjectURL(url);
    url = null;
    wrapper.remove();
  }

  on<Event>(star_button, 'click', () => {
    void toggle_star();
  });
  on<Event>(save_button, 'click', () => {
    if (blob) download_blob(blob, shot_filename(item.title || '截图'));
    else toast('图片还没读出来');
  });
  on<Event>(trash_button, 'click', () => {
    void remove();
  });
  on<Event>(close_button, 'click', close);
  on<Event>(backdrop, 'click', close);

  disposers.push(
    on<KeyboardEvent>(document, 'keydown', event => {
      if (event.key === 'Escape') {
        event.stopPropagation();
        close();
      }
    }),
  );

  sync_star();
  void load_image();
}
