/** 插件自身的小设置，存在本地。 */

const AUTO_OPEN_KEY = 'yueji-guanjia.auto-open-library';

/** 切换角色卡时是否自动打开这张卡的收藏库。默认开。 */
export function load_auto_open(): boolean {
  try {
    return window.localStorage.getItem(AUTO_OPEN_KEY) !== 'off';
  } catch (error) {
    console.warn('[月季管家] 读取自动打开设置失败', error);
    return true;
  }
}

export function save_auto_open(value: boolean): void {
  try {
    window.localStorage.setItem(AUTO_OPEN_KEY, value ? 'on' : 'off');
  } catch (error) {
    console.warn('[月季管家] 保存自动打开设置失败', error);
  }
}
